import sys
sys.path.insert(0, os.path.dirname(__file__))
from locales_more import fr_more, en_more
def merge(a, b):
    for k, v in b.items():
        if isinstance(v, dict) and isinstance(a.get(k), dict): merge(a[k], v)
        else: a[k] = v
merge(fr, fr_more); merge(en, en_more)

def keys(d, p=''):
    out = set()
    for k, v in d.items():
        out |= keys(v, f'{p}{k}.') if isinstance(v, dict) else {p + k}
    return out
assert keys(fr) == keys(en), keys(fr) ^ keys(en)
for name, data in (('fr.default.json', fr), ('en.json', en)):
    with open(os.path.join(L, name), 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2); f.write('\n')
# Snippet qui transmet toutes les chaînes de l'éditeur au script (traduites par Shopify)
he = sorted(k[len('hero_editor.'):] for k in keys(fr) if k.startswith('hero_editor.'))
lines = ['{%- comment -%} Généré par scripts/gen-locales.py — ne pas modifier à la main. {%- endcomment -%}',
         '<script type="application/json" data-ed-strings>', '  {']
lines += [f'    "{k}": {{{{ \'hero_editor.{k}\' | t | json }}}}{"," if i < len(he) - 1 else ""}' for i, k in enumerate(he)]
lines += ['  }', '</script>']
with open(os.path.join(os.path.dirname(__file__), '..', 'theme', 'snippets', 'hero-editor-strings.liquid'), 'w', encoding='utf-8') as f:
    f.write('\n'.join(lines) + '\n')
print(len(keys(fr)), 'keys,', len(he), 'editor strings')
